import json, urllib.request, concurrent.futures, collections, datetime

BASE = "http://127.0.0.1:1933"

def get(url):
    with urllib.request.urlopen(url, timeout=30) as r:
        return json.load(r)

lst = get(BASE + "/api/v1/sessions")["result"]
ids = [s["session_id"] for s in lst]
print("TOTAL_SESSIONS", len(ids))

def detail(sid):
    try:
        d = get(BASE + "/api/v1/sessions/" + sid)["result"]
        return sid, d
    except Exception as e:
        return sid, {"error": str(e)}

rows = []
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
    for sid, d in ex.map(detail, ids):
        if "error" in d:
            rows.append((sid, None, None, None, None, "err"))
            continue
        day = (d.get("created_at") or "")[:10]
        me = d.get("memories_extracted") or {}
        total = me.get("total", 0) if isinstance(me, dict) else 0
        rows.append((sid, day, d.get("commit_count", 0), total,
                     d.get("pending_tokens", 0), d.get("last_message_at", "")))

# per-day aggregate for recent days
byday = collections.defaultdict(lambda: [0,0,0,0])  # count, with_mem, commits, pending_sum
for sid, day, cc, me, pend, lm in rows:
    if day is None:
        continue
    b = byday[day]
    b[0]+=1
    if me and me>0: b[1]+=1
    b[2]+= (cc or 0)
    b[3]+= (pend or 0)

for day in sorted(byday)[-14:]:
    c, wm, cc, ps = byday[day]
    print(f"DAY {day} sessions={c} with_mem={wm} no_mem={c-wm} commits={cc} pending_sum={ps}")

# detail of last 2 days sessions without memories
print("--- RECENT NO-MEM SESSIONS (created >= 2026-11-25) ---")
for sid, day, cc, me, pend, lm in rows:
    if day and day >= "2026-11-25" and not (me and me>0):
        print(f"{day} {sid} commit={cc} mem={me} pending={pend} lastmsg={lm}")

